decision_questions.default:
{
  "version": 3,
  "questions": [
    {
      "id": "action",
      "enabled": true,
      "type": "choice",
      "instructions": "根据近期群聊判断机器人现在应该怎么做。reply 表示发言，既包括针对某条消息回复，也包括自然参与讨论或插话；即使被 @ 或引用，也可以选择 none 不回复。",
      "role": "action",
      "use_threshold": true,
      "options": [
        {
          "id": "none",
          "criteria": "现在不适合发言，保持沉默",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        },
        {
          "id": "reply",
          "criteria": "现在适合发言：可以针对某条具体消息回复，也可以自然参与当前讨论或插话，不必强行引用某一条",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        }
      ],
      "triggers": [
        {
          "event": "message_received"
        }
      ],
      "ask_private": false
    },
    {
      "id": "idle_action",
      "enabled": true,
      "type": "choice",
      "instructions": "会话已经沉默一段时间。判断现在是否适合主动开口。",
      "role": "action",
      "use_threshold": true,
      "options": [
        {
          "id": "none",
          "criteria": "现在仍应保持沉默，不要主动开口",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        },
        {
          "id": "proactive",
          "criteria": "现在适合在冷场后主动开口",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        }
      ],
      "triggers": [
        {
          "event": "silence_elapsed"
        }
      ]
    },
    {
      "id": "target_message_id",
      "enabled": true,
      "type": "choice",
      "instructions": "如果决定发言，可以针对哪一条消息？若不针对某一条特定消息，可选 latest。",
      "role": "target",
      "use_threshold": false,
      "options": [
        {
          "id": "latest",
          "criteria": "沿用会话上下文，自然参与当前话题",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        },
        {
          "id": "*",
          "criteria": "{描述}",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        }
      ],
      "triggers": [
        {
          "question": "action",
          "option": "reply",
          "ask_with_parent": true
        }
      ]
    },
    {
      "id": "length",
      "enabled": true,
      "type": "choice",
      "instructions": "如果发言，回复应该简短还是稍详细？",
      "role": "answer",
      "use_threshold": false,
      "options": [
        {
          "id": "short",
          "criteria": "简短回复，一两句即可",
          "session_hint": "本轮回复策略：请给出简短、自然的回复，一两句即可。",
          "weight": 1.0,
          "tool": ""
        },
        {
          "id": "long",
          "criteria": "更完整、稍详细的回复",
          "session_hint": "本轮回复策略：请给出稍详细、完整的回复，但仍保持自然。",
          "weight": 1.0,
          "tool": ""
        }
      ],
      "triggers": [
        {
          "question": "action",
          "option": "reply",
          "ask_with_parent": true
        },
        {
          "question": "idle_action",
          "option": "proactive",
          "ask_with_parent": true
        }
      ]
    },
    {
      "id": "use_meme",
      "enabled": true,
      "type": "boolean",
      "instructions": "这次回复是否适合配上一张表情包？没有合适的表情时应为否。",
      "role": "answer",
      "use_threshold": true,
      "true_session_hint": "",
      "true_weight": 1.0,
      "true_tool": "send_meme",
      "false_session_hint": "",
      "false_weight": 1.0,
      "false_tool": "",
      "triggers": [
        {
          "question": "action",
          "option": "reply",
          "ask_with_parent": true
        },
        {
          "question": "idle_action",
          "option": "proactive",
          "ask_with_parent": true
        }
      ]
    },
    {
      "id": "meme_id",
      "enabled": true,
      "type": "choice",
      "instructions": "若需要配图，请根据描述选择最合适的一张表情包；不合适则选 none。只根据描述选择，不要假设你能看到原图。",
      "role": "meme",
      "use_threshold": true,
      "options": [
        {
          "id": "none",
          "criteria": "不配表情包",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        },
        {
          "id": "*",
          "criteria": "{描述}",
          "session_hint": "",
          "weight": 1.0,
          "tool": ""
        }
      ],
      "triggers": [
        {
          "question": "use_meme",
          "option": "true"
        }
      ]
    }
  ]
}
